const $=(s,root=document)=>root.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,body,extraHeaders={}){const headers=body===undefined?{}:{'Content-Type':'application/json',...extraHeaders};const r=await fetch(url,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body)});let d={};try{d=await r.json()}catch{} if(!r.ok)throw Object.assign(new Error(d.error||'Something went wrong.'),{data:d,status:r.status});return d}
function nav(path){history.pushState({},'',path);renderRoute()} window.addEventListener('popstate',renderRoute);
function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;document.body.append(n);setTimeout(()=>n.remove(),3000)}
function brand(){return `<a class="brand" href="/" data-nav="/"><span class="brand-mark">↗</span>SyncShield</a>`}
